1	import assert from 'node:assert/strict';
2	import {BackgroundColorField} from '@src/components/settings/email-design/design-fields/background-color-field';
3	import {ButtonColorField} from '@src/components/settings/email-design/design-fields/button-color-field';
4	import {DEFAULT_EMAIL_DESIGN} from '@src/components/settings/email-design/types';
5	import {DividerColorField} from '@src/components/settings/email-design/design-fields/divider-color-field';
6	import {EmailDesignProvider} from '@src/components/settings/email-design/email-design-context';
7	import {HeaderBackgroundField} from '@src/components/settings/email-design/design-fields/header-background-field';
8	import {LinkColorField} from '@src/components/settings/email-design/design-fields/link-color-field';
