}

interface EmailDesignContextValue extends ColorPickerCoordination {
    settings: EmailDesignSettings;
    onSettingsChange: (updates: Partial<EmailDesignSettings>) => void;
    accentColor: string;
}

const EmailDesignContext = createContext<EmailDesignContextValue | undefined>(undefined);

interface EmailDesignProviderProps {
    settings: EmailDesignSettings;
    onSettingsChange: (updates: Partial<EmailDesignSettings>) => void;
    accentColor: string;
    children: ReactNode;
}

export const EmailDesignProvider = ({settings, onSettingsChange, accentColor, children}: EmailDesignProviderProps) => {
    // Tracks color pickers that are currently open (or opening). Stored in a ref
    // so escape handlers can read the latest state synchronously without waiting
    // for a re-render.
    const openColorPickers = useRef(new Map<string, () => void>());

    const registerColorPicker = useCallback((id: string, close: () => void) => {
        openColorPickers.current.set(id, close);
    }, []);

    const unregisterColorPicker = useCallback((id: string) => {
        openColorPickers.current.delete(id);
    }, []);

    const isColorPickerOpen = useCallback(() => openColorPickers.current.size > 0, []);

    const closeColorPickers = useCallback(() => {
        const closers = Array.from(openColorPickers.current.values());
