        settings,
        onSettingsChange,
        accentColor,
        registerColorPicker,
        unregisterColorPicker,
        isColorPickerOpen,
        closeColorPickers
    }), [settings, onSettingsChange, accentColor, registerColorPicker, unregisterColorPicker, isColorPickerOpen, closeColorPickers]);

    return (
        <EmailDesignContext.Provider value={value}>
            {children}
        </EmailDesignContext.Provider>
