import EmailDesignModal from '@src/components/settings/email-design/email-design-modal';
import {ButtonColorField} from '@src/components/settings/email-design/design-fields/button-color-field';
import {DEFAULT_EMAIL_DESIGN} from '@src/components/settings/email-design/types';
import {EmailDesignProvider} from '@src/components/settings/email-design/email-design-context';
import {fireEvent, render, screen} from '@testing-library/react';

const renderModal = (onClose = () => {}) => render(
    <EmailDesignProvider accentColor="#ff0088" settings={DEFAULT_EMAIL_DESIGN} onSettingsChange={() => {}}>
        <EmailDesignModal
            open
            preview={<div>preview</div>}
            sidebar={<ButtonColorField />}
            testId="welcome-email-customize-modal"
            title="Welcome emails"
            onClose={onClose}
            onSave={() => {}}
        />
    </EmailDesignProvider>
);

describe('scratch escape', function () {
    it('keeps modal open when Escape pressed while picker open (mounted)', function () {
        let closed = false;
        renderModal(() => {
            closed = true;
        });

        fireEvent.click(screen.getByText('Button color'));
        // popover content should be mounted now
        fireEvent.keyDown(document.body, {key: 'Escape', code: 'Escape'});

        assert.equal(closed, false, 'onClose should not be called');
        assert.ok(screen.getByTestId('welcome-email-customize-modal'), 'modal still present');
    });

    it('closes modal when Escape pressed with no picker open', function () {
        let closed = false;
        renderModal(() => {
            closed = true;
        });

        fireEvent.keyDown(document.body, {key: 'Escape', code: 'Escape'});
        assert.equal(closed, true, 'onClose should be called');
    });
});
